+/// Execution revalidates membership before constructing an artifact verifier
+/// or dispatching a provider. A credential-bearing environment and fake
+/// publishers make an ordering regression observable: any cargo, gh, or git
+/// push invocation creates the external-effects log.
+#[test]
+fn malformed_membership_before_execute_never_reaches_credentials_or_provider() {
+    let (dir, release_commit) = release_commit_fixture();
+    let external = tempfile::tempdir().unwrap();
+    let root = dir.path();
+    let planned_intent = plan_intent(root, external.path(), &release_commit);
