+    let entry = planned.decision.entries[0].clone();
+    let slot = callisto_model::ArtifactSlotId::new(
+        entry.package.clone(),
+        entry.target_version.clone(),
+        "x86_64-unknown-linux-gnu",
+        "core-crate.tar.gz",
+        callisto_model::GitHubRepository::parse("example/core-crate").unwrap(),
+        ".github/workflows/release.yml",
+        callisto_model::CommitSha::parse(&release_commit).unwrap(),
+    )
+    .unwrap();
+    let mut operations = planned.operations.clone();
+    operations.push(callisto_model::ReleaseOperation::artifact_upload(slot.clone(), vec![]).unwrap());
+    let intent = callisto_model::ReleaseIntentV1::new(
+        planned.decision.clone(),
+        planned.snapshot.clone(),
+        planned.trust_profile,
+        operations,
+        vec![slot.clone()],
+    )
+    .unwrap();
+    let artifact_dir = external.path().join("artifacts");
+    fs::create_dir_all(&artifact_dir).unwrap();
+    let bytes = b"attested core-crate bytes";
+    fs::write(artifact_dir.join(&slot.asset_name), bytes).unwrap();
+    let digest = callisto_model::ArtifactDigest::from_bytes(bytes);
+    let source_commit = match &intent.snapshot.source {
+        callisto_model::SourceIdentity::GitCommit { sha } => sha.clone(),
+        callisto_model::SourceIdentity::HermeticContent { .. } => panic!("fixture must use Git commit trust"),
+    };
+    let manifest = callisto_model::ArtifactManifestV1::new(
+        &intent,
+        vec![callisto_model::ArtifactManifestEntryV1 {
+            slot: slot.clone(),
+            digest: digest.clone(),
+            byte_length: bytes.len() as u64,
+            attestation: callisto_model::GitHubArtifactAttestationV1 {
+                repository: slot.attestation_policy.repository.clone(),
+                workflow_path: slot.attestation_policy.workflow_path.clone(),
+                workflow_commit: slot.attestation_policy.workflow_commit.clone(),
+                subject_digest: digest,
+                source_commit,
+            },
+        }],
+    )
+    .unwrap();
+    // Control: this exact slot, manifest, and bytes are attestation-eligible.
+    // The old execute ordering called this verifier before revalidation, so
+    // removing the production ordering repair would reach `gh` here.
+    struct AttestationControl(std::sync::atomic::AtomicUsize);
+    impl callisto_model::CommandRunner for AttestationControl {
+        fn run(
+            &self,
+            program: &str,
+            args: &[&str],
+            _cwd: &Path,
+        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
+            assert_eq!(program, "gh", "artifact verification must invoke only gh");
+            assert!(
+                args.starts_with(&["attestation", "verify"]),
+                "control must exercise attestation verification, got {args:?}"
+            );
+            self.0.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
+            Ok(callisto_model::CommandOutput {
+                exit_code: Some(0),
+                stdout: String::new(),
+                stderr: String::new(),
+            })
+        }
+    }
+    let control = AttestationControl(std::sync::atomic::AtomicUsize::new(0));
+    callisto_graph::commands::verify_artifact_manifest(&intent, &manifest, &artifact_dir, &control).unwrap();
+    assert_eq!(
+        control.0.load(std::sync::atomic::Ordering::SeqCst),
+        1,
+        "the control proves this fixture would invoke gh attestation verification before the repaired membership boundary"
+    );
+    let intent_path = external.path().join("attested-intent.json");
+    let manifest_path = external.path().join("artifact-manifest.json");
+    fs::write(&intent_path, serde_json::to_vec(&intent).unwrap()).unwrap();
+    fs::write(&manifest_path, serde_json::to_vec(&manifest).unwrap()).unwrap();
+    let state = external.path().join("release-state.json");
+    let (bin, log, forge_marker, git_trace) = fake_publishers(external.path(), &release_commit, false);
+
+    fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = [\"").unwrap();
+    let path = format!("{}:{}", bin.display(), std::env::var("PATH").unwrap());
+    let output = Command::new(env!("CARGO_BIN_EXE_callisto"))
+        .args(["--format", "json", "--cwd", root.to_str().unwrap()])
+        .args([
+            "release",
+            "execute",
+            "--intent",
+            intent_path.to_str().unwrap(),
+            "--state",
+            state.to_str().unwrap(),
+            "--artifact-manifest",
+            manifest_path.to_str().unwrap(),
+            "--artifact-dir",
+            artifact_dir.to_str().unwrap(),
+        ])
+        .env("PATH", path)
+        .env("NPM_TOKEN", "must-not-be-observed")
+        .env("CALLISTO_TEST_LOG", &log)
+        .env("CALLISTO_TEST_GIT_TRACE", &git_trace)
+        .env("CALLISTO_TEST_FORGE_MARKER", &forge_marker)
+        .env("CALLISTO_TEST_REAL_GIT", system_git())
+        .output()
+        .expect("release execute should run");
+
+    assert!(!output.status.success(), "malformed membership must reject execution");
+    let report: serde_json::Value = serde_json::from_slice(&output.stderr).unwrap();
+    assert!(report["error"]["code"]
+        .as_str()
+        .is_some_and(|code| code.contains("E173")));
+    assert!(
+        !log.exists(),
+        "the valid matching artifact roster and bytes would reach fake `gh attestation verify` under the old ordering; membership validation must stop it before credential-aware artifact verification or providers"
+    );
+    assert!(!forge_marker.exists());
+    assert!(
+        !state.exists(),
+        "failed membership validation must not initialize execution state"
+    );
