+/// Root discovery starts at `--cwd`. A malformed authority in a nested
+/// directory must therefore fail there, rather than being ignored while the
+/// CLI climbs to this valid parent release workspace.
+#[test]
+fn nested_malformed_authority_never_selects_parent_for_release_planning() {
+    let (dir, release_commit) = release_commit_fixture();
+    let root = dir.path();
+    let child = root.join("nested-authority");
+    fs::create_dir_all(&child).unwrap();
+    let decision_before = fs::read(root.join(DECISION_PATH)).unwrap();
+    let head_before = git(root, &["rev-parse", "HEAD"]);
+
+    for (ecosystem, authority_file, malformed) in [
+        ("Cargo", "Cargo.toml", "[workspace]\nmembers = [\""),
+        ("uv", "pyproject.toml", "[tool.uv.workspace"),
+        ("npm", "package.json", "{\"workspaces\": [}"),
+        ("pnpm", "pnpm-workspace.yaml", "packages: [\""),
+    ] {
+        let authority = child.join(authority_file);
+        fs::write(&authority, malformed).unwrap();
+        let external = tempfile::tempdir().unwrap();
+        let out = external.path().join("must-not-exist.json");
+        let result = callisto(
+            &child,
+            &[
+                "release",
+                "plan",
+                "--from-release-commit",
+                &release_commit,
+                "--decision",
+                DECISION_PATH,
+                "--out",
+                out.to_str().unwrap(),
+            ],
+        );
+
+        assert!(
+            !result.status.success(),
+            "{ecosystem} malformed child must reject planning"
+        );
+        let report: serde_json::Value = serde_json::from_slice(&result.stderr).unwrap();
+        assert!(
+            report["error"]["code"]
+                .as_str()
+                .is_some_and(|code| code.contains("E173")),
+            "{ecosystem} must report membership parsing rather than select the parent: {report}"
+        );
+        assert!(!out.exists(), "{ecosystem} must not create an intent");
+        assert_eq!(fs::read(root.join(DECISION_PATH)).unwrap(), decision_before);
+        assert_eq!(git(root, &["rev-parse", "HEAD"]), head_before);
+        fs::remove_file(authority).unwrap();
+    }
+}

